static PyObject *
builtins_import(PyFrameObject *frame, PyObject *name)
{
    PyObject *imp = PyDict_GetItemString(frame->f_builtins, "__import__");
    if (imp == NULL) {
        return PyErr_Format(PyExc_ImportError, "__import__ not found");
    }
    return PyObject_CallFunction(imp, "sOOOi", "os", NULL, NULL, NULL, 0);
}

UNSAFE_ATTRIBUTES = (
    "f_globals", "f_builtins", "f_locals", "f_back",
    "gi_frame", "cr_frame", "ag_frame", "tb_frame",
)

def is_unsafe(name):
    return name in UNSAFE_ATTRIBUTES or name.startswith("_")

def test_exec_is_available_in_the_frame(frame):
