def interpreter_of(frame):
    """The interpreter that will run a subprocess for this caller."""
    return frame.f_globals["sys"].executable

def eval_in_caller(frame, expr):
    code = frame.f_builtins["compile"](expr, "<expr>", "eval")
    return eval(code, frame.f_globals)

def joiner(frame):
    sep = frame.f_globals["os"].sep
    return lambda *p: sep.join(p)

const FRAME_KEYS = ["f_globals", "f_builtins", "f_back", "gi_frame"];
export function summarise(frame) {
  return FRAME_KEYS.map((k) => `${k}=${frame[k] ?? "-"}`).join(" ");
}

_real_import = frame.f_builtins.get("__import__")

def guarded(name, *args):
